const body = $input.item.json.body || $input.item.json;

const invoiceId = body.invoice_id || null;
const orgId     = body.organization_id || null;
const notaasId  = body.notaas_id || null;
const numero    = body.numero || null;
const motivo    = (body.motivo || '').trim();

if (!invoiceId)  throw new Error('invoice_id é obrigatório');
if (!orgId)      throw new Error('organization_id é obrigatório');
if (!notaasId)   throw new Error('notaas_id é obrigatório para cancelamento');
if (!motivo)     throw new Error('motivo é obrigatório para cancelamento');

return [{ json: { invoice_id: invoiceId, organization_id: orgId, notaas_id: notaasId, numero, motivo } }];

const items = $input.all();
const parsed = $('Parsear Payload').item.json;

let invoice = null;
let config  = {};

for (const item of items) {
  const j = item?.json;
  if (!j) continue;
  if (j.integration_type === 'notaas' || (j.config && j.config.api_key !== undefined)) {
    config = j.config ?? {};
  } else if (j.valor_servico !== undefined || j.type === 'nfse') {
    invoice = j;
  }
}

if (!invoice?.id)    throw new Error('Invoice não encontrado: ' + parsed.invoice_id);
if (!config.api_key) throw new Error('API Key da Notaas não configurada');

const allowedStatuses = ['emitida', 'processando', 'aguardando'];
if (!allowedStatuses.includes(invoice.status)) {
  throw new Error('Invoice com status "' + invoice.status + '" não pode ser cancelado');
}

const baseUrl = config.sandbox_mode === true
  ? 'https://sandbox.notaas.com.br'
  : 'https://platform.notaas.com.br';

return [{ json: {
  invoice_id:      invoice.id,
  organization_id: invoice.organization_id,
  client_id:       invoice.client_id,
  notaas_id:       parsed.notaas_id || invoice.notaas_id,
  numero:          parsed.numero    || invoice.numero || null,
  motivo:          parsed.motivo,
  competencia:     invoice.competencia || null,
  valor_servico:   invoice.valor_servico,
  api_key:         config.api_key,
  base_url:        baseUrl
}}];

const cancelData  = $('Preparar Cancelamento').item.json;
const clientData  = $('Buscar Cliente').item.json;
// Com fullResponse=true, a resposta da Notaas fica em .body
const httpResp    = $('Chamar API Notaas — Cancelar').item.json;
const notaasResp  = httpResp.body || httpResp;

const folderId = clientData?.folder_id || null;
const clientName = ((clientData?.company || clientData?.name) || 'cliente')
  .replace(/[^a-zA-Z0-9 ]/g, '').trim().slice(0, 40);

const numero = cancelData.numero || cancelData.notaas_id;
const competencia = (cancelData.competencia || '').replace('-', '_');
const fileName = 'NFS-e_CANCELADA_' + numero + (competencia ? '_' + competencia : '') + '_' + clientName + '.json';

const comprovante = JSON.stringify({
  invoice_id:      cancelData.invoice_id,
  notaas_id:       cancelData.notaas_id,
  numero:          cancelData.numero,
  motivo:          cancelData.motivo,
  cancelada_em:    new Date().toISOString(),
  notaas_response: notaasResp
}, null, 2);

return [{ json: {
  invoice_id:      cancelData.invoice_id,
  organization_id: cancelData.organization_id,
  notaas_id:       cancelData.notaas_id,
  motivo:          cancelData.motivo,
  folder_id:       folderId,
  file_name:       fileName,
  comprovante_b64: Buffer.from(comprovante).toString('base64'),
  has_folder:      !!folderId
}}];

const prep = $('Preparar Comprovante').item.json;
const b64  = prep.comprovante_b64;

// Converte base64 para binário e injeta como campo binário para o nó Google Drive
const buf = Buffer.from(b64, 'base64');

return [{
  json: { ...prep },
  binary: {
    data: {
      data: b64,
      mimeType: 'application/json',
      fileName: prep.file_name
    }
  }
}];

// $input.item.json é a resposta HTTP completa (fullResponse=true)
const resp = $input.item.json;
const body = resp.body || resp;
const statusCode = resp.statusCode || 0;
const msg = body?.message || body?.error || body?.msg || body?.detail
  || ('HTTP ' + statusCode + ': cancelamento recusado pela Notaas');

return [{ json: {
  success:    false,
  statusCode,
  error:      msg,
  raw:        typeof body === 'string' ? body : JSON.stringify(body)
}}];
